"""strings stored in an HDF5 from Python2 may look like
     "b'xxx'", that is containg "b".  strip these out here
    """
def h5str(`obj: Any) -> object {
    out = str(`obj);
    if (out.startswith("b'") and out.endswith("'")) {
        out = out[2:-1];
    }
    return out;
}

"""
    Formats a list (['bla',0,'bla']) into an ODS path format ('bla.0.bla')

    :param path: list of strings and integers

    :return: ODS path format
    """
def l2o(path: Any) -> object {
    return '.'.join(filter(None, map(str, path)));
}

